import{ref}from"vue";import{defineStore}from"pinia";import{useToast}from"vue-toast-notification";import"vue-toast-notification/dist/theme-sugar.css";import{useRoute}from"vue-router";export const useCustomStore=defineStore("custom",()=>{const isShowPass=ref(!1),isShowMenu=ref(!1),$toast=useToast(),route=useRoute(),showPassHandler=()=>{isShowPass.value=!isShowPass.value},toast=(message,type)=>{"success"==type?$toast.success(message,{position:"top-right",duration:4e3}):"info"==type?$toast.info(message,{position:"top-right",duration:4e3}):$toast.error(message,{position:"top-right",duration:4e3})},toggleUser=()=>{isShowMenu.value=!isShowMenu.value},isRoute=path=>route.path===path,formatDate=inputDate=>{const months=["January","February","March","April","May","June","July","August","September","October","November","December"],date=new Date(inputDate),monthName=months[date.getMonth()],day=date.getDate(),year=date.getFullYear(),formattedDate=`${monthName} ${day}, ${year}`;return formattedDate};return{isShowPass:isShowPass,showPassHandler:showPassHandler,toast:toast,isShowMenu:isShowMenu,toggleUser:toggleUser,isRoute:isRoute,formatDate:formatDate}});